const searchSN = $('Google Search — Sénégal').first().json;
const searchCI = $('Google Search — CI & Cameroun').first().json;
const trendsSN = $('Google Trends — Sénégal').first().json;
const elearning = $('Google Search — Tendances e-learning').first().json;

const allResults = [];

// Parse Google Search results
for (const source of [searchSN, searchCI, elearning]) {
  const items = source?.items || [];
  for (const item of items) {
    allResults.push({
      title: item.title || '',
      snippet: item.snippet || '',
      url: item.link || '',
      source: 'google_search'
    });
  }
}

// Parse Google Trends RSS (XML as string)
if (typeof trendsSN === 'string' || trendsSN?.data) {
  const raw = typeof trendsSN === 'string' ? trendsSN : JSON.stringify(trendsSN);
  const titles = raw.match(/<title>([^<]+)<\/title>/g) || [];
  for (const t of titles.slice(1, 11)) {
    allResults.push({
      title: t.replace(/<\/?title>/g, ''),
      snippet: 'Tendance Google Trends Sénégal',
      url: '',
      source: 'google_trends'
    });
  }
}

// Deduplicate by title similarity
const seen = new Set();
const unique = allResults.filter(r => {
  const key = r.title.toLowerCase().substring(0, 50);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return [{ json: { merged_sources: unique, count: unique.length, date: new Date().toISOString() } }];

const response = $input.first().json;
const today = new Date().toISOString().split('T')[0];

let parsed;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing réponse Gemini: ' + e.message);
}

const socialIdeas = (parsed.social_media_ideas || []).map(idea => ({
  Date: today,
  Sujet: idea.subject,
  Angle: idea.angle,
  Pertinence_Locale: idea.why_relevant_locally,
  Reseaux: (idea.networks || []).join(', '),
  Format: idea.format,
  Score: idea.relevance_score,
  Source: idea.source_url,
  Hashtags_Locaux: (idea.hashtags_local || []).join(', '),
  Status: 'nouveau'
}));

const articleIdeas = (parsed.article_ideas || []).map(idea => ({
  Date: today,
  Titre_SEO: idea.subject,
  Mot_Cle: idea.main_keyword,
  Angle_Local: idea.why_relevant_locally,
  Volume_Estime: idea.search_volume_estimate,
  Score: idea.relevance_score,
  Status: 'nouveau'
}));

const courseIdeas = (parsed.course_ideas || []).map(idea => ({
  Date: today,
  Titre: idea.subject,
  Niveau: idea.target_level,
  Audience: idea.target_audience,
  Besoin_Local: idea.why_needed_locally,
  Duree: idea.estimated_duration,
  Score: idea.relevance_score,
  Status: 'nouveau'
}));

const highScoreItems = [
  ...socialIdeas.filter(i => i.Score >= 8),
  ...articleIdeas.filter(i => i.Score >= 8),
  ...courseIdeas.filter(i => i.Score >= 8)
];

return [{
  json: {
    social_ideas: socialIdeas,
    article_ideas: articleIdeas,
    course_ideas: courseIdeas,
    geo_context: parsed.geo_context || {},
    high_score_items: highScoreItems,
    has_urgent: highScoreItems.length > 0
  }
}];
